package com.mbox.staff
import org.json.JSONArray
fun canReadFulfillmentHistory(a:StaffIdentity?)=a!=null&&listOf("reconciliation.view","order.history.view","order.history.all").any(a::allows)
fun fulfillmentHistoryPath(kind:String,date:String,table:String,page:Int):String{require(kind in listOf("prepared","delivered")&&page in 0..2000&&table.length<=80);if(date.isNotBlank())require(java.time.LocalDate.parse(date).toString()==date);return "/api/operations/history?workKind=$kind&page=$page&table="+LiveCommand.part(table.trim())+(if(date.isBlank())""else "&businessDate="+LiveCommand.part(date))}
fun validateFulfillmentHistory(h:LiveHistory,page:Int){h.validate(page);serverInstant(h.source.getString("generatedAt"));java.time.LocalDate.parse(h.date);for(o in h.orders)for(i in o.getJSONArray("items").objects()){if(i.has("workQuantity"))require(i.getInt("workQuantity")>=0);for(k in listOf("preparedAt","deliveredAt"))i.textOrNull(k)?.let(::serverInstant)};val shared=h.source.optJSONArray("sharedDeliveries")?:JSONArray();val rows=shared.objects();require(rows.map{it.getString("receiptId")}.distinct().size==rows.size);for(r in rows){require(r.getString("source")=="shared_pickup_device");r.getString("tableCode");r.getString("pickupTableCode");serverInstant(r.getString("deliveredAt"));for(i in r.getJSONArray("items").objects()){i.getString("itemId");i.getString("name");require(i.getInt("quantity")>0&&i.getString("kind") in listOf("original","remake"));for(k in listOf("specification","itemNote","orderNote"))i.getString(k)}}}
